using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Nexora.Domain.Customers;
namespace Nexora.Infrastructure.Persistence;
public sealed class CustomerConfiguration:IEntityTypeConfiguration<Customer>{public void Configure(EntityTypeBuilder<Customer>b){b.ToTable("customers", DatabaseSchemas.Customers);b.HasKey(x=>x.Id);b.Property(x=>x.Name).HasMaxLength(200).IsRequired();b.Property(x=>x.Phone).HasMaxLength(40);b.Property(x=>x.Email).HasMaxLength(320);b.Property(x=>x.Notes).HasMaxLength(4000);b.Property(x=>x.Status).HasMaxLength(30);b.HasIndex(x=>new{x.TenantId,x.Name});b.HasIndex(x=>new{x.TenantId,x.Status});b.HasOne<Nexora.Domain.Tenancy.Tenant>().WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Cascade);}}
